class Solution {
    public int numFactoredBinaryTrees(int[] arr){
        Arrays.sort(arr);
        long mod=1000000007L,answer=0;
        Map<Integer,Long> ways=new HashMap<>();
        for(int i=0;i<arr.length;i++){
            long count=1;
            for(int j=0;j<i;j++)if(arr[i]%arr[j]==0&&ways.containsKey(arr[i]/arr[j]))count=(count+ways.get(arr[j])*ways.get(arr[i]/arr[j]))%mod;
            ways.put(arr[i],count);
            answer=(answer+count)%mod;
        }
        return(int)answer;
    }
}

